/*!40000 ALTER TABLE `food` DISABLE KEYS */;
INSERT  IGNORE INTO `food` VALUES (1,'南翔小笼包','皮薄得能看见里面的汤汁，咬开先吸一口鲜汤，再连皮带馅吃。肉馅紧实、汤汁清亮，配一碟香醋，是上海人从小吃到大的味道。','面粉、猪前腿肉、皮冻、姜末','猪前腿肉剁成细馅，加姜末、酱油、糖调味，拌入切碎的皮冻；面团擀成极薄的圆皮，包入馅料后捏出十八道褶；上笼旺火蒸六分钟，皮透汁亮即可出笼。吃时先开窗吸汤，再蘸香醋连皮带馅一起入口。','清同治年间起源于嘉定南翔镇，最初是镇上小店的早点，如今成了上海点心的招牌。',129,'黄浦区','flavornav/foods/2026/11/a3da406bdc6449c4badd5343536a56b6.jpg',2,'热爱生活的小烟',1,88,'2026-11-10 20:14:30','2026-11-10 20:15:47','鲜、咸','主食'),(2,'宣威火腿','肉色红润、脂白如玉，咸鲜中带着发酵的醇香。蒸一片配饭，或炒青椒，鲜味能提亮整盘菜，是云南人的年货。','宣威猪后腿、盐','选猪后腿修整后上盐，反复揉搓腌制一个月；再经晾挂、发酵一年以上，表面结绿霉、内部析出盐霜；吃时切片蒸熟或炒菜。','与金华火腿齐名，因产于宣威而得名，切片后肥瘦红白分明。',2690,'麒麟区','flavornav/foods/2026/11/0bf0e959f3174b36a578cc7667b9ea09.jpg',3,'吃货阿蛮',1,247,'2026-11-10 20:14:30','2026-11-10 20:15:47','咸、鲜','生鲜原材'),(3,'手把肉','羊肉煮得恰到好处，用手一撕就下来。肉香纯粹没有膻味，蘸点韭菜花，越嚼越鲜，是草原上最豪迈的一顿。','带骨羊肉、盐、葱、姜','羊肉带骨剁成大块，冷水下锅，只放葱姜和少量盐；大火烧开后转小火煮四十分钟，肉刚熟即捞出；用手抓着吃，蘸一点韭菜花酱或盐。','蒙古族传统吃法，讲究原汤原味，不加多余调料。',893,'新城区','flavornav/foods/2026/11/3b71bf040e9c4123a768dccf89af62bf.jpg',4,'深夜食堂常客',1,114,'2026-11-10 20:14:30','2026-11-10 20:15:47','鲜、咸','菜肴'),(4,'老北京炸酱面','手擀面条配小碗干炸的黄酱肉丁，再码上黄瓜丝、豆芽、青豆等时令菜码。拌开后酱香浓郁、面条筋道，菜码带来清脆的口感，是胡同里最踏实的家常味道。','手擀面、干黄酱、五花肉丁、黄瓜丝、豆芽、青豆','干黄酱用黄酒澥开，五花肉丁煸出油后下酱小火慢炸，炸到酱色发亮、油酱分离才算成；面条手擀后煮至断生，捞出过凉水，拌上炸酱和黄瓜丝、豆芽、青豆等菜码。吃时讲究小碗干炸，酱要裹住面条而不流汤。','老北京人家最寻常的一碗面，讲究小碗干炸、菜码齐全，夏天吃过水面，冬天吃锅挑儿。',35,'东城区','flavornav/foods/2026/11/9d80bf1187124a99bd13f0058c75e359.jpg',5,'慢慢来比较快',1,89,'2026-11-10 20:14:31','2026-11-10 20:15:47','咸、香','主食'),(5,'回锅肉','二刀肉先煮后切薄片，下锅煸到边缘卷起像灯盏窝，再加豆瓣豆豉炒出红油。肉片肥而不腻、咸鲜微辣，青蒜苗一断生就起锅，香得能多吃两碗饭。','二刀肉、青蒜苗、郫县豆瓣、甜面酱、豆豉','整块二刀肉冷水下锅，加姜葱煮至七成熟，捞出晾凉切成薄片；锅中少油，下肉片煸炒至卷曲成灯盏窝，逼出多余油脂；加豆瓣、豆豉、甜面酱炒出红油，最后下青蒜苗断生即可。','源于民间祭祀用的白煮肉，第二天回锅再炒，意外成就了川菜之首。',2405,'锦江区','flavornav/foods/2026/11/dfb3e84bb6834b7ba1be9828a2a61f11.jpg',6,'老饕不挑食',1,85,'2026-11-10 20:14:31','2026-11-10 20:15:47','辣、香、咸','菜肴'),(6,'太和板面','面条宽厚筋道，摔出来的面更有嚼头。羊肉臊子香辣，红油浮在汤上，一碗下去又辣又暖，是阜阳人的心头好。','宽面、羊肉、辣椒油、青菜','面团反复揉搓后擀成宽面片，在案板上摔打拉长，下锅煮熟；羊肉切丁加辣椒和香料炒成臊子，浇在面上，加一勺红油和青菜。','皖北名吃，因在案板上摔面而得名，面条宽而筋道。',1532,'颍州区','flavornav/foods/2026/11/2b17c98debbc42b39c981d04dfbe8a22.jpg',7,'一只咸鱼干',1,137,'2026-11-10 20:14:31','2026-11-10 20:15:47','辣、香','主食'),(7,'油焖大虾','虾壳红亮、虾肉紧实弹牙，甜咸的酱汁裹在虾身上。连壳都想吮一遍，是胶东人家宴客时最受欢迎的一道。','对虾、葱姜、白糖、番茄酱、料酒','对虾剪去须脚，从背部挑出虾线；锅中下油，放葱姜爆香，倒入大虾煎至两面变红；加料酒、白糖、番茄酱和少量水，盖盖焖三分钟，大火收汁至浓稠，让酱汁裹住虾身。','胶东沿海的经典做法，虾要选渤海湾的对虾才够鲜。',1763,'市南区','flavornav/foods/2026/11/e496fe0086314df6a453cf98ff8d8d04.jpg',8,'巷口那家店',1,129,'2026-11-10 20:14:31','2026-11-10 20:15:47','鲜、香、甜','菜肴'),(8,'广式烧鹅','鹅皮烤得枣红透亮，咬下去咔嚓一声，油脂的香立刻漫开，鹅肉却还嫩。蘸一点酸梅酱，酸甜把油腻压下去，是广东烧腊里最有排面的一道。','黑鬃鹅、五香粉、麦芽糖、酸梅酱','鹅洗净后从尾部灌入五香盐水，缝口后烫皮、刷麦芽糖水，挂起风干数小时；入炭炉以荔枝木明火烤制，期间转动让其受热均匀，烤至表皮枣红发亮、油脂滴落。斩件后配酸梅酱解腻。','新会古井烧鹅最负盛名，荔枝木炭火和风干环节是皮脆的关键。',487,'荔湾区','flavornav/foods/2026/11/4e083aa570dd467b847011684ca7db00.jpg',9,'锅气爱好者',1,216,'2026-11-10 20:14:31','2026-11-10 20:15:47','香、咸、油腻','菜肴'),(9,'桂林米粉','米粉滑溜，卤水咸香浓郁，锅烧外酥里嫩。配上酸豆角和花生，拌开后每根粉都挂着卤汁，是桂林最日常的一碗。','圆米粉、卤水、锅烧、酸豆角、花生','米粉用开水烫软沥干；浇上熬制的卤水，铺锅烧（炸酥的猪肉）、牛肉片；加酸豆角、花生、葱花和辣椒，拌匀吃。讲究卤水香浓、米粉爽滑。','桂林人的早餐，卤水配方各家不同，是粉店的命根子。',2291,'秀峰区','flavornav/foods/2026/11/e68694eb74bd4f6ab5b3609a3000ea15.jpg',10,'碳水收割机',1,114,'2026-11-10 20:14:31','2026-11-10 20:15:47','鲜、香、咸','主食'),(10,'新疆大盘鸡','鸡肉炖得酥烂，土豆粉糯吸汁，皮带面宽厚筋道。麻辣咸香的汤汁裹住面条，一大盘端上来，几个人分着吃最热闹。','土鸡、土豆、青红椒、皮带面、豆瓣酱','鸡剁块，土豆切滚刀块；锅中下油炒糖色，倒入鸡块翻炒上色，加豆瓣酱、干辣椒和香料；添水炖二十分钟，放土豆再炖十分钟；最后下皮带面拌汤汁吃。','发源于新疆沙湾一带，一大盘鸡配宽面，是公路边的招牌菜。',3139,'天山区','flavornav/foods/2026/11/654d0531ec3e4677a935683160ac60b2.jpg',11,'今天也要好好吃饭',1,181,'2026-11-10 20:14:31','2026-11-10 20:15:47','辣、香','菜肴'),(11,'鸭血粉丝汤','奶白的鸭汤里泡着鸭血、鸭肠、鸭肝和粉丝，料足得几乎要溢出来。汤鲜而不腥，鸭血嫩滑，撒上香菜和辣油，冬天喝一碗浑身发暖。','鸭血、鸭肠、鸭肝、粉丝、豆腐果、香菜','鸭架熬成奶白汤底；鸭血切块、鸭肠鸭肝处理干净后焯熟；粉丝泡软，连同鸭血、豆腐果一起下汤煮开；盛碗后铺鸭肠鸭肝，撒香菜、榨菜末，喜辣的加一勺辣油。','南京街头最常见的平民小吃，一碗汤里能吃遍鸭子全身。',1278,'玄武区','flavornav/foods/2026/11/2d90ccfb634e4e56b448c6ca91eca04c.jpg',2,'热爱生活的小烟',1,263,'2026-11-10 20:14:32','2026-11-10 20:15:47','鲜、咸、香','汤羹'),(12,'南昌瓦罐汤','瓦罐煨出来的汤清亮见底，肉饼嫩滑、汤味醇厚。配一碗南昌拌粉，一干一汤，是南昌人从小喝到大的味道。','猪肉饼、鸡蛋、香菇、墨鱼、瓦罐','猪肉剁成饼状，加香菇、墨鱼等配料放入小瓦罐；加水和调料，罐口封锡纸；放入大瓦缸中，用木炭火煨四小时以上，汤清味浓。','南昌人的早餐标配，一罐汤配一碗拌粉，是街头巷尾的日常。',1651,'东湖区','flavornav/foods/2026/11/6a9f2eb5f8704ba28ec4503f0731bb1a.jpg',3,'吃货阿蛮',1,194,'2026-11-10 20:14:32','2026-11-10 20:15:47','鲜、咸','汤羹'),(13,'开封灌汤包','提起像灯笼、放下似菊花，皮薄得能看见里面的汤。先咬开小口吸汤，鲜得眯眼，再蘸醋把皮和馅吃掉，是开封的招牌早点。','面粉、猪肉馅、皮冻、姜末','猪肉馅加姜末、酱油调好，拌入切碎的皮冻；面团擀成薄皮，包入馅料捏出十八道褶；上笼旺火蒸十分钟，出笼后包子鼓胀透亮，先开窗喝汤再吃。','开封第一楼包子闻名，皮薄馅大、汤汁丰盈是它的招牌。',1899,'龙亭区','flavornav/foods/2026/11/27ff19f77ad64f37b767f055895500d3.jpg',4,'深夜食堂常客',1,161,'2026-11-10 20:14:32','2026-11-10 20:15:47','鲜、香','主食'),(14,'金华火腿','切开后肉色红润、脂白如玉，咸鲜醇厚。炖汤、蒸鱼、炒菜时放几片就能提鲜，是江南厨房里的秘密武器。','金华两头乌猪后腿、盐','选两头乌猪后腿，修整后分批上盐，反复翻堆腌制一个月；再经洗晒、晾挂、发酵近一年，表面结出绿霉、内部析出盐霜才算成品。','与宣威火腿、如皋火腿并称中国三大名腿，工艺已被列入非遗。',1426,'婺城区','flavornav/foods/2026/11/500adee2a793451eb4a344991228628b.jpg',5,'慢慢来比较快',1,202,'2026-11-10 20:14:32','2026-11-10 20:15:47','咸、鲜','生鲜原材'),(15,'清补凉','椰奶香浓，红豆绿豆软糯，西瓜清甜，一碗下去透心凉。配料丰富、甜而不腻，是海南人夏夜最爱的甜品。','椰奶、红豆、绿豆、薏米、芋头、西瓜','红豆绿豆薏米提前煮软；芋头切块蒸熟；碗中放入各种配料，倒入冰镇椰奶，加西瓜丁和凉粉，喜欢甜的再加一勺糖水。','海南夏天的消暑神器，海口街头夜里随处可见清补凉摊。',2380,'秀英区','flavornav/foods/2026/11/eb766fbeff934411bfebfa1ddc263024.png',6,'老饕不挑食',1,230,'2026-11-10 20:14:32','2026-11-10 20:15:47','甜、清爽','甜品冻品'),(16,'面窝','中间薄脆、边缘厚软，咬下去咔嚓一声。葱香和米香混着油香，配热干面或米粉，是武汉人早上的固定组合。','大米浆、黄豆浆、葱花、盐','大米和黄豆泡发磨成浆，加盐和葱花搅匀；特制中间凸起的铁勺舀浆，下油锅炸至金黄；脱模后中间薄、边缘厚，外圈软糯、内圈酥脆。','武汉过早的经典搭配，一碗热干面配两个面窝最满足。',2044,'江岸区','flavornav/foods/2026/11/7cf1dbb728c049b383804cfaee73df0a.jpg',7,'一只咸鱼干',1,243,'2026-11-10 20:14:32','2026-11-10 20:15:47','香、咸','零食小食'),(17,'剁椒鱼头','大鱼头铺满剁椒上锅猛蒸，红艳艳一片。鱼肉鲜嫩得能用勺子挖，剁椒的咸辣和蒸鱼豉油的鲜混在一起，汤汁拌面是一绝。','胖头鱼头、剁椒、蒸鱼豉油、蒜末、葱花','鱼头从中间剖开洗净，用盐和料酒抹匀腌十分钟；盘底铺姜片葱段，放上鱼头，均匀铺满剁椒和蒜末；上笼旺火蒸十二分钟，出锅淋蒸鱼豉油、撒葱花，再泼一勺热油激香。','湘菜代表，源于湘潭一带，红艳艳的剁椒盖住整个鱼头，是湖南人待客的硬菜。',2147,'芙蓉区','flavornav/foods/2026/11/ca3946935d8c44f49f952b4d64c54c27.jpg',8,'巷口那家店',1,226,'2026-11-10 20:14:32','2026-11-10 20:15:47','辣、鲜、咸','菜肴'),(18,'葡式蛋挞','酥皮一碰就碎，蛋液嫩滑，表面那层焦糖微微发苦。甜中带焦香，配一杯咖啡，是澳门街头最香的一口。','面粉、黄油、鸡蛋、奶油、肉桂','面团包入黄油反复折叠，做成千层酥皮，捏入挞模；蛋液加奶油和糖调好，倒入挞皮；高温烤至表面出现焦糖斑点，出炉撒少许肉桂粉。','源自葡萄牙，经澳门改良后风靡亚洲，焦糖斑点是它的标志。',479,'花地玛堂区','flavornav/foods/2026/11/45b7392be4cf43d2837002508298ed89.jpg',9,'锅气爱好者',1,103,'2026-11-10 20:14:32','2026-11-10 20:15:47','甜、香','甜品冻品'),(19,'兰州牛肉面','汤清味鲜，面条筋道爽滑，牛肉片薄而香。一勺红油下去，鲜辣开胃，是兰州人每天早上的第一口。','拉面、牛肉、牛骨汤、萝卜、辣椒油、香菜','面团加蓬灰水揉至筋道，现场拉成毛细、二细或宽面；面条下锅煮熟捞入碗中；浇上牛骨清汤，铺牛肉片、白萝卜片，加辣椒油、香菜和蒜苗。','兰州人的早餐，讲究一清二白三红四绿五黄，面型有十几种选择。',2986,'城关区','flavornav/foods/2026/11/5835e44d8a6642938f3f4cacd4bb5ca7.jpg',10,'碳水收割机',1,97,'2026-11-10 20:14:33','2026-11-10 20:15:47','鲜、香、辣','主食'),(20,'荔枝肉','肉块炸得卷曲起来，真像剥了壳的荔枝。外酥里嫩，酸甜汁裹得均匀，配着脆爽的荸荠，是福州人宴席上的老面孔。','猪里脊、荸荠、番茄酱、白糖、香醋','里脊肉剞十字花刀，切块后裹淀粉炸至卷曲如荔枝；荸荠切块同炸；锅中调番茄酱、糖、醋成酸甜汁，倒入肉块和荸荠快速翻匀，勾薄芡出锅。','因形似荔枝而得名，是闽菜里的经典甜酸口。',1567,'鼓楼区','flavornav/foods/2026/11/8662bf518a884dc4968db6fb45a5ee20.jpg',11,'今天也要好好吃饭',1,157,'2026-11-10 20:14:33','2026-11-10 20:15:47','酸甜、香','菜肴'),(21,'风干牦牛肉','肉条干硬紧实，撕开能看到纤维。越嚼越出肉香，咸鲜中带着一丝野性，配酥油茶是藏族人待客的零嘴。','牦牛肉、盐、花椒','牦牛肉切成长条，用盐和花椒揉搓；挂在通风阴凉处自然风干一到两个月；吃时撕成小块，或用刀削着吃，越嚼越香。','高原冬季的传统储存方式，风干后肉质紧实、风味独特。',2861,'色尼区','flavornav/foods/2026/11/11a64e994b0a4a7cb4a9b5954adcd0b9.jpg',2,'热爱生活的小烟',1,194,'2026-11-10 20:14:33','2026-11-10 20:15:47','咸、香','零食小食'),(22,'丝娃娃','薄皮裹着十几种脆爽的菜丝，蘸上酸辣汤汁，一口下去又酸又辣又清爽。折耳根的味道很有个性，是贵阳人夏天的最爱。','薄面皮、萝卜丝、黄瓜丝、折耳根、脆哨、酸汤蘸水','面粉摊成薄如纸的圆皮；各种蔬菜切细丝，分盘摆放；吃时把菜丝卷入面皮，包成襁褓状，蘸酸辣汤汁一口吃下。','贵阳街头小吃，因包好的样子像襁褓中的婴儿而得名。',2588,'南明区','flavornav/foods/2026/11/370c907a5ada431090f9d40333021ae2.jpg',3,'吃货阿蛮',1,198,'2026-11-10 20:14:33','2026-11-10 20:15:47','酸、辣、清爽','零食小食'),(23,'雪绵豆沙','外表雪白蓬松像云朵，咬开是绵密的豆沙。甜而不腻，入口即化，吃完一桌咸鲜菜后来一份，刚好解腻。','蛋清、豆沙、淀粉、白糖','蛋清打发至硬性发泡，加淀粉拌匀；豆沙搓成小球，裹上蛋泡糊；下温油慢炸，至外表雪白蓬松；捞出撒白糖，趁热吃外酥内软。','东北传统甜菜，考验打发蛋清和油温控制，是宴席上的压轴甜点。',996,'和平区','flavornav/foods/2026/11/91afff278ef24b8393638720c745ebac.jpg',4,'深夜食堂常客',1,108,'2026-11-10 20:14:33','2026-11-10 20:15:47','甜、香','甜品冻品'),(24,'辣子鸡','鸡块炸得干香酥脆，埋在红彤彤的干辣椒里。一口下去麻辣焦香，越嚼越有味，爱吃辣的人能在辣椒堆里翻半天。','鸡腿肉、干辣椒、花椒、姜蒜','鸡腿肉切小块，加盐和料酒腌好；下油锅炸至外酥里嫩；锅中留油，爆香大量干辣椒和花椒，倒入鸡块翻炒，加姜蒜和调料炒匀，出锅前撒芝麻。','重庆歌乐山的辣子鸡最出名，辣椒里找鸡是这道菜的乐趣。',308,'万州区','flavornav/foods/2026/11/6218bb7263144ee8a53858c27a292e7e.jpg',5,'慢慢来比较快',1,207,'2026-11-10 20:14:33','2026-11-10 20:15:47','辣、香、麻','菜肴'),(25,'云吞面','面条爽脆弹牙，云吞皮薄馅大，能吃到整只虾。汤清味鲜，撒一把韭黄，是香港人从小吃到大的味道。','竹升面、鲜虾云吞、大地鱼汤、韭黄','鲜虾和猪肉做馅，包成小云吞；竹升面煮至爽脆，云吞另煮；碗中放面，铺云吞，浇大地鱼熬的清汤，撒韭黄。','香港面食的代表，讲究汤清、面爽、云吞有虾味。',461,'中西区','flavornav/foods/2026/11/7bdc698265f841969cb27fe5125deb74.jpg',6,'老饕不挑食',1,131,'2026-11-10 20:14:33','2026-11-10 20:15:47','鲜、清爽','主食'),(26,'哈尔滨红肠','肠衣脆、肉质紧实，蒜香和烟熏味很突出。切片配面包，或整根就着啤酒啃，是哈尔滨人最熟悉的零嘴。','猪肉、牛肉、大蒜、黑胡椒、肠衣','猪肉牛肉绞碎，加蒜末、黑胡椒和盐腌渍；灌入肠衣后扎孔排气；送入熏炉用果木屑熏制数小时，表皮呈枣红色、带烟熏香；吃时切片或整根啃。','源自俄式灌肠，秋林里道斯的最有名，是哈尔滨的城市名片。',1156,'道里区','flavornav/foods/2026/11/c42163e1602c4dcaaf8ff66c5564c670.jpg',7,'一只咸鱼干',1,297,'2026-11-10 20:14:33','2026-11-10 20:15:47','咸、香','零食小食'),(27,'排骨年糕','炸得酥香的猪大排配软糯的年糕，浇上甜中带咸的辣酱油。排骨外脆里嫩，年糕吸饱酱汁后油光发亮，一口咸甜交织，是上海人念念不忘的街头味。','猪大排、水磨年糕、辣酱油、面粉','猪大排拍松后裹薄面糊，下锅炸至两面金黄；年糕切片下锅同炸至外脆内软；锅中调辣酱油、糖和少许汤汁烧开，放入排骨和年糕翻匀收汁，让酱汁裹在年糕表面。','上海老字号小吃，流行近百年，排骨配年糕是本地人雷打不动的组合。',130,'徐汇区','flavornav/foods/2026/11/3c0a1c6132fd45ad909d0aa9b01b7760.jpg',8,'巷口那家店',1,230,'2026-11-10 20:14:33','2026-11-10 20:15:47','甜、咸、香','主食'),(28,'过桥米线','汤面浮着鸡油，看着不冒烟其实滚烫。肉片一烫就熟，米线滑溜，汤鲜得能喝见底，是云南最有仪式感的一碗。','米线、鸡汤、生肉片、鹌鹑蛋、蔬菜','老母鸡和猪骨熬成滚烫浓汤，盛入大碗，表面浮一层鸡油保温；生肉片、鹌鹑蛋、蔬菜依次下入汤中烫熟；最后放入米线，稍等片刻即可食用。','蒙自的传统吃法，因送饭要过桥而得名，汤的温度是关键。',2757,'个旧市','flavornav/foods/2026/11/21058626fcb44a6dbebd67b6346435cd.jpg',9,'锅气爱好者',1,238,'2026-11-10 20:14:34','2026-11-10 20:15:47','鲜、香','主食'),(29,'蒙古奶茶','咸口的奶茶，茶香和奶香混着炒米的焦香。喝一口暖胃，泡上奶豆腐和炒米，一碗下去就半饱了，是草原上的待客之道。','砖茶、鲜奶、盐、炒米、奶皮子','砖茶敲碎，加水熬煮出浓茶汤；滤去茶叶，倒入鲜奶和盐，再次烧开；盛碗后加炒米、奶皮子或奶豆腐，咸香浓郁。','蒙古族日常饮品，有客人来必先上一碗奶茶。',894,'回民区','flavornav/foods/2026/11/8894a7d7cfba4b84841a631f548453d4.jpg',10,'碳水收割机',1,203,'2026-11-10 20:14:34','2026-11-10 20:15:47','咸、香','饮品'),(30,'北京烤鸭','选用北京填鸭，经充气、烫皮、挂糖色、晾胚、果木挂炉烤制而成。成菜色泽红润、皮酥肉嫩，片皮后配甜面酱、葱丝与荷叶饼卷食，一口下去油香、酱香、葱香层层叠起，是北京最具代表性的宴客菜。','北京填鸭、甜面酱、葱丝、黄瓜条、荷叶饼','填鸭从翅下开口气泵使皮肉分离，沸水烫皮后刷糖色，挂通风处晾胚六小时以上；果木炭火入炉，炉温约两百度烤至枣红色，出炉趁热片成薄片。片好的鸭皮酥脆、鸭肉细嫩，配甜面酱、葱丝、黄瓜条与荷叶饼卷食，最后再喝一碗鸭架汤收尾。','源于南北朝时期的炙鸭，明代成为宫廷名菜，后传入民间，是北京宴席上当之无愧的头牌。',36,'西城区','flavornav/foods/2026/11/2f4a8bec3f74448a94494397ceb872d3.jpg',11,'今天也要好好吃饭',1,281,'2026-11-10 20:14:34','2026-11-10 20:15:47','香、鲜、油腻','菜肴'),(31,'麻婆豆腐','豆腐嫩得颤巍巍，牛肉末酥香，红油裹着花椒的麻。一勺浇在米饭上，麻辣鲜烫一起涌上来，是川菜里最下饭、也最难做好的一道家常菜。','嫩豆腐、牛肉末、郫县豆瓣、花椒面、蒜苗','嫩豆腐切块，加盐水焯一下去豆腥并定型；牛肉末下锅煸至酥香，加郫县豆瓣炒出红油，添汤下豆腐小火慢烧入味；分三次勾芡让汤汁牢牢挂住豆腐，起锅撒花椒面和蒜苗。讲究麻、辣、烫、香、酥、嫩、鲜、活八字。','清同治年间由成都万福桥边陈麻婆首创，最初是给挑夫下饭的便宜菜，如今成了川菜第一名片。',2406,'青羊区','flavornav/foods/2026/11/80eb4d11536c4e8f8b6d3a4f148395f2.jpg',2,'热爱生活的小烟',1,219,'2026-11-10 20:14:34','2026-11-10 20:15:47','麻、辣、鲜、香','菜肴'),(32,'徽州臭鳜鱼','鱼肉发酵后呈蒜瓣状，闻着臭、吃着鲜。红烧后咸香浓郁，笋丁和五花肉的油香渗进鱼肉里，越吃越有味。','鳜鱼、笋丁、五花肉、辣椒、蒜','鳜鱼用淡盐水腌制，在木桶中压石发酵数天，闻起来发臭、鱼肉却蒜瓣般紧实；下锅前洗净切段，与五花肉丁、笋丁同烧，加酱油、辣椒和蒜，小火焖至入味，收汁出锅。','徽菜代表，闻臭吃香，是徽州人待客的硬菜。',1517,'屯溪区','flavornav/foods/2026/11/b4b11db9aea74da29468e24e764816bf.jpg',3,'吃货阿蛮',1,229,'2026-11-10 20:14:34','2026-11-10 20:15:47','鲜、香、咸','菜肴'),(33,'葱烧海参','海参软糯弹牙，大葱炸出的葱油香浓得化不开。酱汁咸鲜微甜，裹在海参上油亮诱人，是鲁菜里最有排面的一道。','刺参、大葱、高汤、酱油、糖','刺参泡发后焯水去腥；大葱切段，用油慢慢炸至金黄出香，捞出备用；锅中下高汤、酱油、糖和炸好的葱段，放入海参小火煨入味，最后勾芡收汁，把葱油淋在表面。','鲁菜代表菜，讲究以葱提鲜，是宴席上的硬菜。',1751,'历下区','flavornav/foods/2026/11/8282e4a9333e403099a504fed5c1cf64.jpg',4,'深夜食堂常客',1,189,'2026-11-10 20:14:34','2026-11-10 20:15:47','鲜、香、咸','菜肴'),(34,'白切鸡','整鸡浸熟后过冰水，鸡皮爽脆、鸡肉滑嫩，蘸上姜葱蓉和花生油。做法看着简单，火候差一点就柴，是考验粤菜师傅基本功的一道菜。','三黄鸡、姜、葱、花生油、盐','整鸡洗净，放入微沸的葱姜水中浸煮，水要保持似开非开，浸至鸡皮紧实、竹签扎腿无血水；捞出立刻过冰水让鸡皮收紧；斩件摆盘，配姜葱蓉和热花生油调的蘸碟。讲究皮爽、肉滑、骨带血。','粤菜无鸡不成宴的代表，广东人评判一家酒楼的水准，往往先点一只白切鸡。',488,'越秀区','flavornav/foods/2026/11/48fb8a54c6be42d88d1fcce23ec5608a.jpg',5,'慢慢来比较快',1,238,'2026-11-10 20:14:34','2026-11-10 20:15:47','鲜、清爽','菜肴'),(35,'柠檬鸭','鸭肉紧实入味，酸柠檬的清香很特别，酸辣中带着果香。越吃越开胃，夏天没胃口时来一盘，能多吃两碗饭。','鸭子、酸柠檬、酸辣椒、酸姜、蒜','鸭子剁块焯水；锅中下油，爆香酸姜、酸辣椒和蒜，倒入鸭块翻炒；加酸柠檬、酱油和少量水焖煮三十分钟，收汁后撒香菜。','南宁武鸣一带的特色做法，用腌渍的酸柠檬提味，酸香开胃。',2269,'兴宁区','flavornav/foods/2026/11/4a30b95681124a20918f37a0e3fb340f.jpg',6,'老饕不挑食',1,44,'2026-11-10 20:14:34','2026-11-10 20:15:47','酸、辣、香','菜肴'),(36,'馕','刚出炉的馕外脆内软、麦香十足，放凉后变硬但越嚼越香。掰开泡奶茶或夹羊肉串吃，是新疆人最日常的主食。','面粉、盐、酵母、芝麻','面粉加盐和酵母发酵，揉成面团，中间压出花纹；表面刷盐水、撒芝麻；贴入馕坑内壁，烤至金黄鼓起，外脆内软。','维吾尔族主食，耐存放，是新疆人出门必带的干粮。',3140,'沙依巴克区','flavornav/foods/2026/11/259ce2d9ee7a4b18a279a7674a524841.jpg',7,'一只咸鱼干',1,45,'2026-11-10 20:14:35','2026-11-10 20:15:47','香、咸','主食'),(37,'松鼠鳜鱼','鳜鱼剞花刀炸成松鼠状，浇上滚烫的酸甜汁，上桌还在吱吱响。外皮酥脆、鱼肉细嫩，酸甜开胃，是苏州宴席上的头牌。','鳜鱼、番茄酱、白糖、香醋、松子','鳜鱼去骨，鱼肉朝上剞出菱形花刀，用盐和料酒略腌后拍上干淀粉，提尾下油锅炸至金黄卷曲，形似松鼠；另起锅炒番茄酱、糖、醋调成酸甜汁，趁热浇在鱼身上，撒松子仁。上桌时吱吱作响。','苏帮菜的代表，相传与乾隆下江南有关，因浇汁时声响似松鼠而得名。',1312,'虎丘区','flavornav/foods/2026/11/29d68268cf1547d3ae3f6d988156ac42.jpg',8,'巷口那家店',1,76,'2026-11-10 20:14:35','2026-11-10 20:15:47','酸、甜、香','菜肴'),(38,'南昌拌粉','米粉滑溜筋道，辣椒油香而不燥，萝卜干和花生的脆让口感更丰富。拌开红油裹满米粉，配一罐瓦罐汤，完美。','米粉、辣椒油、花生米、萝卜干、葱花','米粉煮熟后过凉水沥干；碗中放辣椒油、酱油、香油和蒜水；米粉入碗，加花生米、萝卜干、酸豆角和葱花，拌匀即食。','南昌早餐的另一半，和瓦罐汤是雷打不动的组合。',1652,'西湖区','flavornav/foods/2026/11/58b2fdd95c3249b5b88b834ee20293dd.jpg',9,'锅气爱好者',1,225,'2026-11-10 20:14:35','2026-11-10 20:15:47','辣、香、咸','主食'),(39,'河南卤面','面条吸饱了肉和豆角的汤汁，干香入味、根根分明。五花肉的油香混着蒜末的辛，是河南人家里最常见的一锅。','细面、五花肉、豆角、蒜','细面先上笼蒸二十分钟；五花肉和豆角炒成菜卤，加汤烧开；把蒸过的面抖散，拌入菜卤，再上笼蒸十五分钟，让面条吸饱汤汁，出锅拌蒜末。','河南家常面食，讲究面蒸两遍、卤汁拌匀，干香不粘。',1887,'中原区','flavornav/foods/2026/11/0bada144b3734e58bbc55f5582d52bae.jpg',10,'碳水收割机',1,38,'2026-11-10 20:14:35','2026-11-10 20:15:47','咸、香','主食'),(40,'东坡肉','五花肉焖得酥烂却不散，色泽红亮如玛瑙，酒香混着甜咸的酱香。用筷子一夹就颤，入口即化、肥而不腻，配米饭能吃两大碗。','五花肉、黄酒、酱油、冰糖、葱姜','五花肉切大方块，焯水后用棉线扎紧；砂锅底铺葱姜，肉皮朝下码好，加黄酒、酱油、冰糖，不加水，小火焖一个半小时；翻面再焖半小时，收汁至红亮。','相传与苏轼治理西湖、犒劳民工有关，是杭帮菜里最富故事性的一道。',1373,'上城区','flavornav/foods/2026/11/64f0947339024f4e934cf3b16f8fa31d.jpg',11,'今天也要好好吃饭',1,57,'2026-11-10 20:14:35','2026-11-10 20:15:47','甜、咸、香','菜肴'),(41,'文昌鸡','鸡皮爽脆、鸡肉嫩滑，蘸上酸甜带辣的桔子汁蘸料，鲜味更突出。肥而不腻、清淡爽口，是海南人待客的头道菜。','文昌鸡、姜、蒜、桔子汁、鸡汤','整鸡放入微沸的鸡汤中浸煮，水保持似开非开，浸至鸡皮紧实、肉刚熟；捞出过冰水，斩件摆盘；蘸料用姜蒜蓉、桔子汁、酱油和鸡汤调成。','海南四大名菜之首，文昌鸡皮薄骨酥，蘸桔子汁是当地特色。',2392,'文昌市','flavornav/foods/2026/11/3410e8059e3c4aafa4e158ee30315b85.jpg',2,'热爱生活的小烟',1,150,'2026-11-10 20:14:35','2026-11-10 20:15:47','鲜、清爽','菜肴'),(42,'沔阳三蒸','米粉裹着肉和鱼，蒸出来油润不腻。肉香、鱼鲜、菜甜各占一角，原汁原味，是湖北人宴席上的老面孔。','米粉、五花肉、草鱼、时蔬','五花肉切片、鱼切块、蔬菜切段，分别用盐和米粉拌匀；按荤素分层码入蒸笼，大火蒸四十分钟；蒸出的油脂被米粉吸收，原汁原味。','湖北沔阳传统蒸菜，讲究蒸肉、蒸鱼、蒸菜三样俱全。',2143,'仙桃市','flavornav/foods/2026/11/727a0d011af84cda9439a914ad2c5edc.jpg',3,'吃货阿蛮',1,281,'2026-11-10 20:14:35','2026-11-10 20:15:47','鲜、香','菜肴'),(43,'口味虾','小龙虾在红油里翻滚，麻辣鲜香直冲鼻子。剥开虾壳，虾肉紧实入味，配一瓶冰啤酒，就是长沙夏天的味道。','小龙虾、干辣椒、花椒、啤酒、姜蒜','小龙虾刷洗干净，剪去虾头前端和虾线；锅中下油，爆香姜蒜、干辣椒和花椒，倒入龙虾翻炒至变红；加啤酒和调料焖煮十五分钟，收汁后撒紫苏和葱花。','长沙夜宵文化的代表，夏天傍晚的夜宵摊上几乎桌桌必点。',2148,'天心区','flavornav/foods/2026/11/07a89d2118f3462984ddefd68a8dc3c6.jpg',4,'深夜食堂常客',1,93,'2026-11-10 20:14:35','2026-11-10 20:15:47','辣、香、麻','菜肴'),(44,'猪扒包','面包烤得酥脆，猪扒厚实多汁，洋葱带来一点甜。咬下去肉汁渗进面包里，简单却满足，是澳门人的日常。','猪扒、面包、黄油、洋葱','猪扒拍松腌制，煎至两面金黄；面包切开，抹黄油烤热；夹入猪扒和洋葱丝，趁热吃，面包外脆内软。','澳门茶餐厅的招牌，猪扒带骨、面包用炭烤的更香。',480,'圣安多尼堂区','flavornav/foods/2026/11/44201c6ce22e43fd8c7a33c84a027504.jpg',5,'慢慢来比较快',1,164,'2026-11-10 20:14:36','2026-11-10 20:15:47','香、咸','主食'),(45,'浆水面','浆水酸得清冽，不像醋那样冲。面条筋道，配上炝过的蒜末辣椒，酸辣清爽，夏天吃一碗浑身舒坦。','手擀面、浆水、芹菜、辣椒、蒜','芹菜等蔬菜发酵制成浆水，取浆水烧开调味；手擀面煮熟捞入碗中，浇上浆水汤；另起锅用油炝蒜末和辣椒，泼在面上。','甘肃夏天消暑的家常面，浆水用蔬菜自然发酵，酸得清爽。',3001,'秦州区','flavornav/foods/2026/11/efccb157ced24e1d8d07766bcda8550a.png',6,'老饕不挑食',1,243,'2026-11-10 20:14:36','2026-11-10 20:15:47','酸、清爽','主食'),(46,'佛跳墙','一坛聚尽山珍海味，汤色金黄浓稠。鲍鱼弹、海参糯、花胶滑，各种鲜味叠在一起，喝一口鲜得说不出话来。','鲍鱼、海参、花胶、鸽蛋、火腿、香菇','各种干货分别泡发、焯水处理；坛底铺竹箅，按耐煮程度分层码入，加高汤和黄酒，用荷叶封口；先大火烧开，再转文火煨五六个小时，让所有食材的鲜味融进汤里。','闽菜之首，相传香味浓到让隔壁寺庙的和尚都想跳墙来尝。',1568,'台江区','flavornav/foods/2026/11/ea7963749c7d4a83b4df8af371e666a7.jpg',7,'一只咸鱼干',1,143,'2026-11-10 20:14:36','2026-11-10 20:15:47','鲜、香','汤羹'),(47,'糌粑','青稞的麦香混着酥油的醇厚，捏成团后口感粗粝扎实。配一口酥油茶，越嚼越香，是高原上最实在的能量来源。','青稞面、酥油、奶渣、白糖','青稞炒熟后磨成粉；碗中放糌粑面，加酥油、奶渣和糖；倒入少量酥油茶，用手捏拌成团，边捏边吃。','藏族传统主食，便于携带，是牧民出门的干粮。',2805,'城关区','flavornav/foods/2026/11/255d5ae5d6f54ad7bf9b710e95c50459.jpg',8,'巷口那家店',1,245,'2026-11-10 20:14:36','2026-11-10 20:15:47','香、咸','主食'),(48,'重庆火锅','红油翻滚、麻辣冲鼻，毛肚脆、鸭肠滑、黄喉爽。蘸一碟香油蒜泥，越辣越想吃，三五好友围一桌，能吃上两个小时。','牛油、辣椒、花椒、毛肚、鸭肠、黄喉','牛油下锅化开，加豆瓣、辣椒、花椒和香料炒出红油，掺骨汤熬成锅底；毛肚七上八下涮十几秒，鸭肠烫到卷曲，黄喉煮到脆嫩；蘸香油蒜泥碟降温提香。','重庆的江湖气都在这口锅里，九宫格和牛油锅底是本地标配。',309,'涪陵区','flavornav/foods/2026/11/3f0e512989944d4e9918abd728d7ce24.jpg',9,'锅气爱好者',1,215,'2026-11-10 20:14:36','2026-11-10 20:15:47','麻、辣、香','菜肴'),(49,'港式蛋挞','挞皮层层起酥，蛋液嫩滑得像布丁。趁热咬一口，酥皮掉渣、蛋香四溢，是香港茶餐厅里最治愈的一口。','面粉、黄油、鸡蛋、牛奶、糖','黄油和面粉搓成酥皮，捏入蛋挞模；鸡蛋、牛奶和糖调成蛋液，过滤后倒入挞皮；烤箱烤至挞皮金黄、蛋面微颤，出炉趁热吃。','港式茶餐厅的标配，分牛油皮和酥皮两派，配一杯奶茶是经典下午茶。',462,'湾仔区','flavornav/foods/2026/11/82d13c5786b940fab95ff2b3b295abbf.jpg',10,'碳水收割机',1,43,'2026-11-10 20:14:36','2026-11-10 20:15:47','甜、香','甜品冻品'),(50,'生煎包','平底锅先煎后焖，底部焦脆、上半部松软。咬开一个小口，滚烫的肉汁就涌出来，芝麻和葱花的香气混在一起，是上海街头最诱人的早餐之一。','面粉、猪肉馅、皮冻、白芝麻、葱花','半发酵面团包入肉馅和皮冻，收口朝下排入平底锅；先煎至底部结壳，再沿锅边淋水加盖焖熟，让蒸汽把上半部蒸透；出锅前撒芝麻和葱花，底脆顶软、一咬爆汁。','二十世纪初在上海茶馆流行起来的点心，最初是配茶吃的，后来成了独立的早点。',131,'长宁区','flavornav/foods/2026/11/dd88e9a28f8945a9b51db9f9b68bc6d0.jpg',11,'今天也要好好吃饭',1,109,'2026-11-10 20:14:36','2026-11-10 20:15:47','香、咸、鲜','主食'),(51,'汽锅鸡','汤清如水却鲜得惊人，鸡肉酥烂脱骨。没有多余调料，喝的就是鸡本身的鲜甜，是云南人待客的滋补汤。','土鸡、姜片、枸杞、汽锅','鸡剁块放入建水紫陶汽锅，加姜片和少量盐；汽锅坐在盛水的汤锅上，靠蒸汽凝结成汤；蒸三到四小时，汤清味浓、鸡肉酥烂。','云南名菜，用建水汽锅蒸制，不加一滴水，全靠蒸汽凝成汤。',2676,'五华区','flavornav/foods/2026/11/2caaf98162eb4a9688905f2f69a5a705.jpg',2,'热爱生活的小烟',1,119,'2026-11-10 20:14:36','2026-11-10 20:15:47','鲜、清爽','汤羹'),(52,'奶豆腐','口感微酸带甜，越嚼越有奶香。直接吃有点硬，泡进热奶茶里就变软，是草原上最常见的零嘴。','鲜奶、酸奶引子','鲜奶发酵后分离出奶清，把凝结的奶块小火慢熬，不断搅拌至浓稠；倒入模具压成型，晾干即成；可直接吃，也可泡奶茶。','蒙古族传统奶食，耐存放，是牧民出门随身带的干粮。',981,'二连浩特市','flavornav/foods/2026/11/33675dd6b6f14ff3be41d3f3c742cf29.jpg',3,'吃货阿蛮',1,247,'2026-11-10 20:14:37','2026-11-10 20:15:47','酸、甜','零食小食'),(53,'豌豆黄','白豌豆煮烂去皮，加糖炒成豆泥后冷凝切块。成品色泽浅黄、细腻如膏，入口即化，甜味清清爽爽，是京式糕点里最不腻人的一味。','白豌豆、白糖','白豌豆泡发后煮烂，去皮过筛成细泥，加白糖小火翻炒至能立住铲子；倒入模具抹平，冷藏定型后切成小方块。成品色泽浅黄、质地细腻，入口一抿就化，甜味清雅不齁。','原是清宫御膳房的小吃，慈禧也爱吃，后由民间仿制，成为春夏时令点心。',37,'石景山区','flavornav/foods/2026/11/7c73df0cff374801a7001d48a1dd6080.jpg',4,'深夜食堂常客',1,297,'2026-11-10 20:14:37','2026-11-10 20:15:47','甜、清爽','甜品冻品'),(54,'担担面','细面拌上红油、芝麻酱和花椒面，再盖一勺芽菜肉臊。面条筋道、麻辣鲜香，臊子干香有嚼劲，拌开后每一根面都油亮入味，是成都人最爱的干拌面。','细面条、猪肉臊子、芽菜、红油、芝麻酱、花生碎','猪肉末加芽菜炒成干香的臊子；碗底放红油、芝麻酱、酱油、花椒面、蒜水调匀；面条煮熟捞入碗中，舀一勺臊子，撒花生碎和葱花。拌开时面要裹住红油，碗底不能留汤，讲究干拌。','因早年小贩挑着担子走街串巷叫卖而得名，是成都街头最老牌的面食之一。',2407,'金牛区','flavornav/foods/2026/11/bff54566a6ae47998205b2440c8b935e.jpg',5,'慢慢来比较快',1,165,'2026-11-10 20:14:37','2026-11-10 20:15:47','麻、辣、香','主食'),(55,'胡适一品锅','一锅层层叠叠，五花肉的油香往下渗，笋干和豆腐包吸饱汤汁。越煮越入味，是徽州人冬天围炉的硬菜。','五花肉、鸡块、笋干、豆腐包、蛋饺','砂锅底铺笋干，依次码上五花肉、鸡块、豆腐包、蛋饺等，层层叠放；加高汤和调料，大火烧开后转小火慢炖两小时，让各层味道互相渗透。','徽州绩溪传统宴客菜，因胡适常以此待客而得名。',1560,'宣州区','flavornav/foods/2026/11/4f2c2bb1a8794bc182059d37c2a43700.png',6,'老饕不挑食',1,194,'2026-11-10 20:14:37','2026-11-10 20:15:47','鲜、香','菜肴'),(56,'把子肉','肉条捆得紧实，卤到软烂不散，肥肉透亮、瘦肉酥香。浇一勺浓稠的卤汁拌饭，咸香油润，是济南人从小吃到大的味道。','五花肉、酱油、冰糖、香料、蒲草','五花肉切成长条，用蒲草或棉线捆扎；入老汤加酱油、冰糖和香料，小火卤两小时以上至肉酥烂；捞出后浇一勺卤汁，配米饭或面条吃。','济南人的米饭杀手，一碗把子肉配米饭是当地最经典的快餐。',1752,'市中区','flavornav/foods/2026/11/22c58927784e46d49a7c4de7461411d7.jpg',7,'一只咸鱼干',1,176,'2026-11-10 20:14:37','2026-11-10 20:15:47','咸、香、油腻','菜肴'),(57,'布拉肠粉','米浆在布上蒸成薄薄一层，卷起肉馅切段，淋甜豉油。粉皮滑得几乎不用嚼，米香清淡，配上鸡蛋和牛肉，是广东人开启一天的方式。','粘米粉、澄面、鸡蛋、牛肉或虾仁、豉油','米浆调好后舀在铺了湿布的蒸盘上，摊薄后放上蛋液、肉片或虾仁，入蒸柜蒸两分钟；用布一抖把肠粉卷起，切段装碟，淋上甜豉油和熟油。米浆要现磨才够滑。','源于广州西关的街头早点，布拉肠粉比抽屉式更薄更滑。',489,'海珠区','flavornav/foods/2026/11/09996ae8e33145bd8b29ed45c92d864f.jpg',8,'巷口那家店',1,279,'2026-11-10 20:14:37','2026-11-10 20:15:47','鲜、咸、顺滑','主食'),(58,'柳州螺蛳粉','汤头鲜辣，酸笋的独特气味冲鼻而来。米粉爽滑、腐竹吸汤、花生酥脆，爱它的人欲罢不能，怕它的人退避三舍。','米粉、螺蛳汤、酸笋、腐竹、木耳、花生','螺蛳和猪骨熬成汤底，加酸笋、辣椒油调味；米粉煮熟捞入碗中，浇螺蛳汤；铺腐竹、木耳、花生、青菜和酸笋，加一勺辣油。','柳州街头小吃，酸笋的味道极具辨识度，如今风靡全国。',2281,'城中区','flavornav/foods/2026/11/90249b337ec44bf8b1230c5c9af9d581.jpg',9,'锅气爱好者',1,285,'2026-11-10 20:14:37','2026-11-10 20:15:47','辣、酸、鲜','主食'),(59,'拉条子','面条筋道有嚼劲，浇头酸辣鲜香，番茄的酸和羊肉的香很搭。拌开后每根面都裹着汤汁，是新疆人最日常的一碗。','面粉、羊肉、番茄、青椒、洋葱','面团抹油醒好，搓成条后拉长下锅煮熟；羊肉切丝，与番茄、青椒、洋葱一起炒成浇头；面条捞出，浇上浇头拌匀。','新疆家常面食，面要拉得细长筋道，浇头各家不同。',3141,'新市区','flavornav/foods/2026/11/093a67fdfa174467869379fe8c22fe37.jpg',10,'碳水收割机',1,291,'2026-11-10 20:14:37','2026-11-10 20:15:47','鲜、辣','主食'),(60,'扬州炒饭','米粒颗颗分明、干爽不粘，鸡蛋、虾仁、火腿、青豆均匀分布。看着简单，火候和配料比例却极考究，是最见功底的炒饭。','籼米、鸡蛋、虾仁、火腿、青豆、香菇','隔夜籼米饭提前打散；鸡蛋炒成蛋花盛出；锅中下虾仁、火腿丁、香菇丁、青豆炒香，倒入米饭大火翻炒至粒粒分明，加盐调味，最后拌入蛋花和葱花出锅。','源于扬州蛋炒饭，随淮扬菜流传海外，是最讲究配料比例的炒饭。',1350,'广陵区','flavornav/foods/2026/11/4f6cce0d0bb74ec08766739db665ba2d.jpg',11,'今天也要好好吃饭',1,299,'2026-11-10 20:14:38','2026-11-10 20:15:47','鲜、咸、香','主食'),(61,'道口烧鸡','鸡皮金黄油亮，肉烂到轻轻一抖就脱骨。香料味渗进每一丝肉里，冷吃最香，是河南人走亲访友的老牌特产。','土鸡、老汤、八味香料、蜂蜜','鸡宰杀造型后抹蜂蜜，下油锅炸至金黄；放入百年老汤，加八味香料，小火焖煮数小时至肉烂脱骨；捞出晾凉，色泽金黄、香味入骨。','中华四大名鸡之一，滑县道口镇的最正宗，老汤是镇店之宝。',1932,'文峰区','flavornav/foods/2026/11/3b5254f45a2e4ad093afb3cc69d7731d.jpg',2,'热爱生活的小烟',1,44,'2026-11-10 20:14:38','2026-11-10 20:15:47','香、咸','菜肴'),(62,'缙云烧饼','饼皮烤得焦脆鼓起，里面是梅干菜的咸香和猪肉的油润。咬下去的脆响过后是梅干菜的回甘，配一碗豆浆就是丽水人的早饭。','面粉、梅干菜、猪肉、芝麻','面团包入梅干菜肉馅，擀成薄饼，表面刷糖水撒芝麻；饼坯贴入炭炉内壁，用炭火余温烘烤至鼓起焦黄，取出趁热吃。','丽水缙云传统小吃，相传有千年历史，饼桶烤制是它的特色。',1454,'莲都区','flavornav/foods/2026/11/846eb5ae877b408ab78a18b4d19fc170.jpg',3,'吃货阿蛮',1,144,'2026-11-10 20:14:38','2026-11-10 20:15:47','香、咸','零食小食'),(63,'海南粉','米粉细滑，卤汁咸香，牛肉干有嚼劲，酸菜和花生带来脆爽。拌开后每一口都有不同配料，是海口街头最日常的一碗。','细米粉、牛肉干、花生、酸菜、芝麻、卤汁','细米粉烫软沥干；碗中放米粉，铺牛肉干丝、炸花生、酸菜、豆芽和芝麻；浇上卤汁和香油，拌匀吃。','海口人的早餐，分粗粉和细粉，卤汁是各家秘方。',2381,'龙华区','flavornav/foods/2026/11/0444deeb84ce4a7ca5baadda8e0c02ad.jpg',4,'深夜食堂常客',1,288,'2026-11-10 20:14:38','2026-11-10 20:15:47','咸、香','主食'),(64,'毛氏红烧肉','不放酱油，全靠糖色上色，肉块红亮得像琥珀。肥肉入口即化，甜中带一点干辣椒的微辣，是湖南人餐桌上的头牌。','五花肉、冰糖、干辣椒、八角、姜','五花肉切块焯水；锅中下少量油炒冰糖至枣红色，倒入肉块翻炒上色；加干辣椒、八角、姜片和少量水，小火慢烧一小时，收汁至油亮。与普通红烧肉不同，全程不放酱油，靠糖色上色。','因毛泽东喜爱而得名，湘潭韶山一带的做法最正宗。',2165,'雨湖区','flavornav/foods/2026/11/0c12e00208754c9c819fd489c7b36956.png',5,'慢慢来比较快',1,147,'2026-11-10 20:14:38','2026-11-10 20:15:47','甜、咸、香','菜肴'),(65,'酿皮子','酿皮筋道爽滑，面筋吸饱汤汁。辣椒油香、香醋酸、芥末冲，一口下去酸辣开胃，是甘肃人夏天的最爱。','面粉、辣椒油、香醋、蒜水、芥末','面粉洗出面筋，面浆沉淀后舀入盘中蒸成薄皮；酿皮切条，配面筋块；浇辣椒油、香醋、蒜水和芥末，拌匀吃。','甘肃街头小吃，夏天吃最爽口，酸辣筋道。',2987,'七里河区','flavornav/foods/2026/11/252f27f514ed462e981d6949f59c5ac9.jpg',6,'老饕不挑食',1,131,'2026-11-10 20:14:38','2026-11-10 20:15:47','辣、酸、香','主食'),(66,'沙县拌面扁肉','拌面裹满花生酱，香浓顺滑；扁肉皮薄馅嫩，汤清味鲜。一干一汤搭配着吃，简单却让人踏实，是无数打工人的深夜食堂。','面条、花生酱、猪肉馅、面皮、高汤','面条煮熟沥干，拌入花生酱、酱油和香油；扁肉用薄面皮包猪肉馅，下高汤煮熟；一碗干拌面配一碗扁肉汤，是沙县小吃的经典组合。','沙县小吃走向全国的代表，一干一汤，便宜又管饱。',1591,'三元区','flavornav/foods/2026/11/9c91648c25024ca8a03c10237c66cdfb.jpg',7,'一只咸鱼干',1,196,'2026-11-10 20:14:38','2026-11-10 20:15:47','香、咸','主食'),(67,'藏面','面条偏硬有嚼劲，牛骨汤清鲜，牦牛肉丁香而不膻。撒点葱花，热乎乎一碗下肚，是拉萨人一天的开始。','碱面、牦牛肉、牛骨汤、葱花','碱面煮熟后用凉水过一遍，盘成小份；牦牛肉切丁，牛骨熬汤；吃时将面在汤中烫热，加牛肉丁、葱花和盐，汤面同吃。','拉萨街头最常见的早餐，面偏硬，配一壶甜茶是标配。',2806,'堆龙德庆区','flavornav/foods/2026/11/95063a1fea6f4df5a3fd47f565e246c0.jpg',8,'巷口那家店',1,289,'2026-11-10 20:14:39','2026-11-10 20:15:47','鲜、咸','主食'),(68,'万州烤鱼','鱼皮烤得焦脆，鱼肉却还嫩。麻辣汤汁咕嘟咕嘟地煮着，配菜吸饱汤汁，越吃越辣、越辣越停不下筷子。','草鱼、豆芽、藕片、辣椒、花椒','草鱼剖开腌入味，放在烤架上炭火烤至两面焦香；烤盘底铺豆芽藕片，放上烤鱼；另起锅炒麻辣汤汁浇在鱼上，边加热边吃，最后加配菜煮。','发源于重庆万州，先烤后炖，是长江边的特色吃法。',310,'渝中区','flavornav/foods/2026/11/ec288b4f25114210b44630551d82368e.jpg',9,'锅气爱好者',1,276,'2026-11-10 20:14:39','2026-11-10 20:15:47','辣、香、麻','菜肴'),(69,'菠萝油','外皮酥脆、面包松软，夹着的冰黄油正在融化。一口下去，甜、咸、冰、热同时在嘴里，是香港人最爱的下午茶。','菠萝包、黄油、面粉、糖','菠萝包烤至表面金黄，酥皮裂开成菠萝纹；趁热从中间横切一刀，夹入一片厚切冰黄油；黄油遇热微微融化，咬下去冷热交替。','香港茶餐厅的招牌，冰火菠萝油的名字就来自这种冷热口感。',463,'东区','flavornav/foods/2026/11/711b08bba86f4487a5450090d23934dd.jpg',10,'碳水收割机',1,212,'2026-11-10 20:14:39','2026-11-10 20:15:47','甜、香','零食小食'),(70,'葱油拌面','小葱在油里慢慢炸到焦香，拌进刚煮好的面条里，再加一勺甜咸适口的酱油汁。做法简单到极致，葱香却浓得化不开，是上海人心里最熨帖的一碗面。','细面、小葱、酱油、猪油','小葱洗净晾干，切成寸段，冷油下锅小火慢炸，炸到葱段焦黄发脆、葱香彻底渗进油里；酱油加糖烧开调成葱油汁。面条煮熟沥干，舀一勺葱油、淋两勺汁拌匀，撒上炸脆的葱段。','上海弄堂里最平常的一碗面，过去是姆妈们用隔夜的小葱做的快手早饭。',132,'静安区','flavornav/foods/2026/11/e3110601873c45ed94cd74f3c919e518.jpg',11,'今天也要好好吃饭',1,215,'2026-11-10 20:14:39','2026-11-10 20:15:47','咸、香','主食'),(71,'烤全羊','羊皮烤得金红发亮、酥脆化渣，里面的肉却还嫩。孜然和洋葱的香气渗进肉里，切一块蘸韭菜花，是草原的味道。','整羊、盐、孜然、洋葱、香料','整羊处理干净，用盐、孜然和洋葱腌渍数小时；架在炭火上慢慢转动烤制，期间刷油和调料，烤至外皮金红酥脆、内部熟透；上桌时切成块，配奶茶和韭菜花。','蒙古族待客的最高礼节，多在节庆和婚宴上出现。',895,'玉泉区','flavornav/foods/2026/11/b2adb89397b64d829b1e01a1ed7f7d17.jpg',2,'热爱生活的小烟',1,138,'2026-11-10 20:14:39','2026-11-10 20:15:47','香、咸','菜肴'),(72,'豆汁焦圈','用绿豆发酵取汁熬制，味道微酸带涩，是老北京独有的早点。配上刚出锅的焦圈和一碟辣咸菜丝，酸香、酥脆、咸辣一起入口，才算喝出了地道的老北京味儿。','绿豆、焦圈、辣咸菜丝','绿豆浸泡磨浆后发酵，滤出的汁水小火熬煮，边煮边搅防止糊底；焦圈用面粉加矾碱盐和面，抻成圆圈下油锅炸至金黄酥脆。喝时趁热吸溜，配焦圈和辣咸菜丝，酸、脆、咸三种口感交替。','清代已有记载，是老北京早点摊上的固定组合，本地人爱到骨子里，外地人往往喝不惯。',38,'海淀区','flavornav/foods/2026/11/0f5f1eb762944d28886ac33f62d6f36a.jpg',3,'吃货阿蛮',1,27,'2026-11-10 20:14:39','2026-11-10 20:15:47','酸、涩、香','零食小食'),(73,'三大炮','糯米团摔出三声响，裹上黄豆面、淋红糖汁。外干香、内软糯，红糖的甜和黄豆的香裹在一起，现做现吃时糯米还是温热的，甜得很舒服。','糯米、黄豆面、红糖汁、芝麻','糯米蒸熟后舂成糍粑，分成小团；师傅把糯米团用力摔在案板上，发出砰砰砰三声响，再滚上炒香的黄豆面，淋红糖汁、撒芝麻。现做现吃，糯米还带着温热。','成都传统名小吃，因摔打糯米团时连响三声而得名，常见于庙会和小吃街。',2408,'武侯区','flavornav/foods/2026/11/a70749d2d0b64c39a93fedd90622874b.jpg',4,'深夜食堂常客',1,261,'2026-11-10 20:14:39','2026-11-10 20:15:47','甜、香','甜品冻品'),(74,'淮南牛肉汤','牛骨熬出的汤又白又浓，粉丝滑、豆饼香、牛肉烂。一勺辣椒油下去，鲜辣滚烫，配个烧饼泡着吃，是淮南人一天的开始。','牛肉、牛骨、粉丝、豆饼、辣椒油','牛骨和牛肉加香料久熬成奶白浓汤；牛肉切片，粉丝泡软，豆饼切丝；碗中放粉丝、豆饼和牛肉片，浇滚汤烫熟，加辣椒油、香菜和蒜苗，配烧饼吃。','淮南街头早餐，汤要滚、辣要够，配烧饼是标配。',1486,'大通区','flavornav/foods/2026/11/88458ace1890456cb47e99dcf523fe6b.jpg',5,'慢慢来比较快',1,85,'2026-11-10 20:14:39','2026-11-10 20:15:47','鲜、香、辣','汤羹'),(75,'煎饼卷大葱','杂粮饼薄而韧，卷上脆生生的大葱和甜面酱，一口下去面香、葱辣、酱甜全来了。越嚼越有味道，是山东人最熟悉的早餐。','杂粮面糊、大葱、甜面酱、鸡蛋','玉米面、小米面调成稀糊，舀在烧热的鏊子上摊成薄饼，打一个鸡蛋抹匀，撒葱花香菜；饼边翘起时揭下，抹甜面酱，放上整根大葱卷起。','沂蒙山区的传统主食，越嚼越香，是山东人豪爽性格的写照。',1840,'兰山区','flavornav/foods/2026/11/c178f2ce2bce4e07af9093d958ca0196.jpg',6,'老饕不挑食',1,183,'2026-11-10 20:14:39','2026-11-10 20:15:47','咸、香','主食'),(76,'潮汕牛肉丸','牛肉反复捶打成浆，挤成丸子汆熟，弹牙到能在碗里跳。咬开一口爆出肉汁，牛香十足，蘸沙茶酱吃最地道，是潮汕火锅必点。','黄牛后腿肉、盐、淀粉、清汤','黄牛后腿肉去筋，用铁棒反复捶打成肉浆，加盐和少量淀粉搅打上劲；挤成丸子下微沸的水中汆熟，丸子浮起即可。吃时配沙茶酱或清汤，讲究弹到能跳起来。','潮汕手打牛肉丸技艺，捶打次数和力度决定弹牙程度，是潮汕火锅的灵魂。',520,'龙湖区','flavornav/foods/2026/11/916e4f634a194dbaaf0eccdfad230935.jpg',7,'一只咸鱼干',1,78,'2026-11-10 20:14:39','2026-11-10 20:15:47','鲜、清爽','菜肴'),(77,'南宁老友粉','酸笋和豆豉的香味很冲，汤头酸辣开胃。扁粉滑嫩，吸饱汤汁后一口下去，酸、辣、鲜全有了，是南宁人的心头好。','扁米粉、酸笋、豆豉、猪肉、辣椒','锅中下油，爆香豆豉、酸笋和辣椒，加肉片炒散；添高汤烧开，下扁米粉煮软；调咸酸味，撒葱花出锅，汤粉同吃。','南宁人的日常，酸辣开胃，感冒时来一碗特别舒服。',2270,'青秀区','flavornav/foods/2026/11/05831992dc2242348e04ec252066a92c.jpg',8,'巷口那家店',1,104,'2026-11-10 20:14:40','2026-11-10 20:15:47','酸、辣、香','主食'),(78,'手抓饭','米粒油亮、颗颗分明，胡萝卜甜、羊肉香。孜然的香味贯穿始终，一大盘端上来，配一碗酸奶刚好解腻。','大米、羊肉、胡萝卜、洋葱、孜然','羊肉切块煸炒出油；下洋葱和胡萝卜条炒软；加盐和孜然，添水烧开；倒入泡好的大米，铺平后小火焖四十分钟，出锅拌匀。','维吾尔族待客主食，过去用手抓着吃，现在多用勺子。',3142,'水磨沟区','flavornav/foods/2026/11/fcf0cd67c521449884148f04998bc956.jpg',9,'锅气爱好者',1,266,'2026-11-10 20:14:40','2026-11-10 20:15:47','香、咸','主食'),(79,'蟹黄汤包','皮薄透亮，兜着一包蟹黄汤汁。先开窗吸一口，鲜得眉毛都要掉，再蘸香醋把皮和馅吃掉，是江南早茶里最矜贵的一笼。','面粉、蟹黄、猪前腿肉、皮冻、姜','猪肉馅拌入蟹黄和皮冻，调味后冷藏；面团擀成极薄的皮，包入馅料捏出细褶，上笼旺火蒸八分钟；出笼后汤包鼓胀透亮，吃时先咬小口吸汤，再蘸醋连皮吃。','靖江、泰州一带的早茶名点，皮薄如纸、汤多不破是检验手艺的标准。',1279,'秦淮区','flavornav/foods/2026/11/4f94c11e6b1345208d53b389388d9da3.jpg',10,'碳水收割机',1,157,'2026-11-10 20:14:40','2026-11-10 20:15:47','鲜、咸','主食'),(80,'洛阳牡丹燕菜','萝卜丝蒸得晶莹剔透，形似燕窝，浇上清鸡汤鲜得很。汤清味醇、入口即化，是洛阳水席里最讲究的一道。','白萝卜、火腿、香菇、蛋皮、高汤','白萝卜切极细的丝，裹淀粉上笼蒸透，抖散后形似燕窝；码入碗中，铺火腿丝、香菇丝和蛋皮丝，浇上清鸡汤，上笼再蒸十分钟，出笼时摆成牡丹花形。','洛阳水席的头道菜，因形似牡丹而得名，是水席的门面。',1908,'老城区','flavornav/foods/2026/11/2e0180c790db4dc2b16ba7118872d28a.jpg',11,'今天也要好好吃饭',1,249,'2026-11-10 20:14:40','2026-11-10 20:15:47','鲜、清爽','菜肴'),(81,'片儿川','雪菜的咸鲜、笋片的脆嫩、肉片的滑，全都融在一碗汤面里。面条筋道，汤头清鲜，是杭州人雷打不动的早餐。','碱水面、雪菜、笋片、猪里脊片','里脊切片上浆，雪菜切末，笋切薄片；锅中下猪油，爆香雪菜和笋片，加高汤烧开，下面条煮至断生，最后放肉片烫熟，调咸鲜味出锅。','杭州面馆的头牌，奎元馆的最出名，雪菜和笋是灵魂。',1374,'拱墅区','flavornav/foods/2026/11/adc98900129f4b4da8d105dba8dfaa6a.jpg',2,'热爱生活的小烟',1,193,'2026-11-10 20:14:41','2026-11-10 20:15:47','鲜、咸','主食'),(82,'长沙臭豆腐','黑乎乎的一块，闻着冲鼻，咬开却外脆内嫩。辣汁灌进去，一口下去又臭又香又辣，是长沙夜市里排队最长的那一摊。','豆腐、卤水、辣椒汁、蒜蓉、香菜','豆腐用特制卤水浸泡发酵至表面发黑；下油锅炸至外壳鼓起酥脆；捞出后用筷子在中间戳个洞，灌入辣椒汁、蒜蓉和香菜，趁热吃。','火宫殿臭豆腐最出名，毛主席曾题词称赞，是长沙街头的标志性小吃。',2149,'岳麓区','flavornav/foods/2026/11/0ed7da1ad25841de8e0253d02e2ad1e5.jpg',3,'吃货阿蛮',1,200,'2026-11-10 20:14:41','2026-11-10 20:15:47','辣、香','零食小食'),(83,'手抓羊肉','羊肉肥瘦相间，煮得软嫩不膻。撒点椒盐，用手抓着啃，肉汁在嘴里爆开，是西北人最豪迈的吃法。','羊肋条、盐、花椒、姜','羊肋条剁成大块，冷水下锅；加花椒、姜和少量盐，大火烧开后转小火煮四十分钟；肉刚熟即捞出，蘸椒盐或蒜泥吃，用手抓着啃。','甘肃临夏一带的传统吃法，讲究羊肉新鲜、原汁原味。',3056,'临夏市','flavornav/foods/2026/11/5fd0433f04314d91a46f1da37741a101.jpg',4,'深夜食堂常客',1,119,'2026-11-10 20:14:41','2026-11-10 20:15:47','鲜、咸','菜肴'),(84,'肉燕','肉燕皮薄得透光，入口爽滑带一点脆。肉馅鲜香，汤头清甜，一碗下去暖胃又满足，是福州宴席上的吉利菜。','猪后腿肉、番薯粉、肉馅、高汤','猪后腿肉去筋捶成肉泥，拌入番薯粉反复擀压成薄如纸的肉燕皮；包入猪肉馅，捏成燕尾形；下高汤煮熟，撒葱花和胡椒粉。','福州太平燕，婚宴寿宴必上，寓意平安吉祥。',1569,'仓山区','flavornav/foods/2026/11/2a6ca6cdfaa04f9082aabbc7f70bc419.jpg',5,'慢慢来比较快',1,257,'2026-11-10 20:14:41','2026-11-10 20:15:47','鲜、香','主食'),(85,'毛血旺','鸭血嫩滑、毛肚爽脆，红油汤里泡着各种配料。麻辣鲜香一起涌上来，配米饭能连吃两碗，是重庆江湖菜的代表。','鸭血、毛肚、黄喉、午餐肉、黄豆芽','豆芽焯熟垫底；锅中炒豆瓣和火锅底料出红油，加高汤烧开；依次下毛肚、黄喉、午餐肉和鸭血煮熟；连汤倒入盆中，撒干辣椒和花椒，泼热油激香。','发源于重庆磁器口，最初是码头工人吃的下水菜。',311,'大渡口区','flavornav/foods/2026/11/375501a9feee485aa0d3d5152593e4e1.jpg',6,'老饕不挑食',1,68,'2026-11-10 20:14:41','2026-11-10 20:15:47','辣、麻、鲜','菜肴'),(86,'羊肉烧麦','皮薄得透光，里面是满满的羊肉馅。咬开一口，滚烫的肉汁流出来，葱香混着羊肉的鲜，配砖茶解腻刚刚好。','面粉、羊肉馅、大葱、姜','羊肉剁碎加葱姜和调料拌成馅；面团擀成薄如纸的皮，包入馅料捏成石榴状；上笼旺火蒸十分钟，出笼时皮薄透亮、汤汁盈盈。','内蒙古早茶的主角，配一壶砖茶，一屉烧麦就是一顿早饭。',896,'赛罕区','flavornav/foods/2026/11/57b5922e044a46d9bb27a1af8d3e657e.jpg',7,'一只咸鱼干',1,111,'2026-11-10 20:14:41','2026-11-10 20:15:47','鲜、香','主食'),(87,'老北京涮羊肉','铜锅清汤，只放葱姜，手切羊肉在滚水里涮十几秒就捞，蘸上麻酱、韭菜花、腐乳调的小料。肉嫩不膻，蘸料醇厚，吃到最后再来瓣糖蒜解腻，是北京冬天的仪式感。','羊上脑、羊后腿、麻酱、韭菜花、腐乳、糖蒜','铜锅加清水，只放葱段、姜片、几粒枸杞，水开后下薄切羊肉片，七上八下涮十几秒即熟；麻酱用温水澥开，加韭菜花、腐乳、香油调成小料。涮完肉再涮白菜、冻豆腐和粉丝，最后喝汤。','源于元代蒙古军中吃法，清代传入北京，铜锅清汤、手切鲜羊肉是正宗标配。',39,'门头沟区','flavornav/foods/2026/11/047e45db45974deeacbea4ee2fa8e7a3.jpg',8,'巷口那家店',1,51,'2026-11-10 20:14:41','2026-11-10 20:15:47','鲜、香、咸','菜肴'),(88,'水煮鱼','鱼片嫩滑得几乎不用嚼，豆芽垫底吸饱汤汁。滚烫的油泼在干辣椒和花椒上，麻辣香瞬间炸开，鱼片白嫩、红油透亮，是下饭又上头的硬菜。','草鱼、黄豆芽、干辣椒、花椒、蛋清','草鱼片成薄片，加盐、蛋清、淀粉上浆；豆芽焯熟垫在盆底；鱼片下微沸的水中滑至变白，捞出铺在豆芽上；干辣椒和花椒在油里炸香，连热油一起泼在鱼片上，滋啦一声激出麻辣香。','由川菜水煮肉片演变而来，二十世纪八十年代在重庆、四川一带流行开来。',2425,'自流井区','flavornav/foods/2026/11/72b077b8eab4483387728adb7ec9332c.jpg',9,'锅气爱好者',1,183,'2026-11-10 20:14:42','2026-11-10 20:15:47','辣、麻、鲜','菜肴'),(89,'毛豆腐','豆腐发酵长毛后下锅煎，外皮焦香、内里软嫩如腐乳。蘸一点辣酱，豆香和发酵的鲜味混在一起，是徽州街头最特别的小吃。','豆腐、菜籽油、辣椒酱、葱','豆腐切块后放在稻草上自然发酵，表面长出一层白色绒毛；平底锅下菜籽油，把毛豆腐逐块煎至两面金黄、绒毛消失；出锅蘸辣椒酱，撒葱花趁热吃。','徽州传统发酵豆制品，街头小摊常见，煎的时候香味能飘半条街。',1518,'黄山区','flavornav/foods/2026/11/be4309b1cf85453881302e2ad10794d8.jpg',10,'碳水收割机',1,181,'2026-11-10 20:14:42','2026-11-10 20:15:47','香、咸','零食小食'),(90,'九转大肠','大肠处理得毫无异味，外层裹着红亮的糖醋汁。入口先是酸甜，接着是香料的复合香气，软糯中带嚼劲，是鲁菜里的功夫菜。','猪大肠、糖、醋、辣椒、肉桂、砂仁','大肠反复清洗去腥，套叠成段后煮至软熟；锅中炒糖色，下大肠段翻炒上色，加醋、酱油、料酒和香料，小火㸆至汤汁浓稠，酸甜香辣咸五味俱全。','清光绪年间济南九华楼创制，因工序繁复如九转仙丹而得名。',1753,'槐荫区','flavornav/foods/2026/11/06491913d07642bf8d88efd0cc594d9d.jpg',11,'今天也要好好吃饭',1,56,'2026-11-10 20:14:42','2026-11-10 20:15:47','甜、酸、辣、香','菜肴'),(91,'姜撞奶','热牛奶撞进姜汁里，静置几分钟就凝成嫩豆腐般的质地。入口顺滑微辛，奶香里带着姜的暖，冷天吃一碗，胃里立刻热起来。','水牛奶、老姜汁、白糖','老姜磨蓉挤汁，每碗放一勺；水牛奶加糖煮至八十度左右，离火稍晾后从高处快速冲入姜汁碗中，静置五到十分钟自然凝固。温度太高会老、太低不凝，讲究撞的手法。','顺德传统甜品，靠姜汁里的酶让牛奶凝固，是岭南糖水铺的招牌。',490,'天河区','flavornav/foods/2026/11/1a192d6a7e0443cfa2b04263308641fa.jpg',2,'热爱生活的小烟',1,279,'2026-11-10 20:14:42','2026-11-10 20:15:47','甜、顺滑','甜品冻品'),(92,'烤包子','外皮烤得金黄酥脆，咬开是满满的羊肉丁和洋葱。孜然的香气混着肉汁，一口一个，是新疆街头最香的零嘴。','面粉、羊肉丁、洋葱、孜然','羊肉切丁，拌洋葱和孜然做馅；面团擀成薄皮，包成方形，贴在馕坑内壁；烤至外皮金黄酥脆，出炉趁热吃。','维吾尔族传统面食，馕坑烤制，外皮酥、内馅香。',3143,'头屯河区','flavornav/foods/2026/11/6b24cca4c42045c582766f3d190eddc1.jpg',3,'吃货阿蛮',1,86,'2026-11-10 20:14:42','2026-11-10 20:15:47','香、咸','零食小食'),(93,'无锡酱排骨','排骨焖到酥烂脱骨，酱汁浓稠发亮，甜中带咸、咸里透鲜。啃起来肉香混着糖香，连骨头都入味，是无锡人从小吃到大的味道。','猪肋排、酱油、冰糖、黄酒、八角','肋排斩段焯水，用清水煮至六成熟；锅中下酱油、冰糖、黄酒和香料，放入排骨大火烧开，转小火焖至骨酥肉烂，最后开大火收汁，让酱汁紧紧裹住排骨，色泽酱红发亮。','无锡三大特产之一，甜出头、咸收口，是无锡菜浓油赤酱的典型。',1289,'锡山区','flavornav/foods/2026/11/c41a7a4c1483481492cee7b56e95b323.jpg',4,'深夜食堂常客',1,134,'2026-11-10 20:14:42','2026-11-10 20:15:47','甜、咸、香','菜肴'),(94,'嘉兴粽子','糯米被肉汁浸得油润发亮，五花肉炖到酥烂，一咬满口咸香。粽叶的清香渗进米里，热吃最糯，是端午前后家家户户的味道。','糯米、五花肉、粽叶、酱油','糯米淘洗后用酱油拌匀；五花肉切块用酱油、糖腌入味；粽叶折成漏斗形，填入米和肉，包成四角粽，用棉线扎紧；大锅水煮三小时以上，让米粒吸饱肉汁。','江南端午食俗，嘉兴鲜肉粽以肥而不腻、米粒油润著称。',1408,'南湖区','flavornav/foods/2026/11/12565fd6386445fea20a7100bc882f8a.jpg',5,'慢慢来比较快',1,113,'2026-11-10 20:14:42','2026-11-10 20:15:47','咸、香','主食'),(95,'土笋冻','晶莹剔透的冻里嵌着沙虫，口感弹滑清凉。蘸上芥末蒜蓉酱，鲜味冲上来，第一次吃需要点勇气，吃惯了会上瘾。','沙虫、酱油、芥末、蒜蓉、香菜','沙虫反复清洗去沙，加水熬煮至胶质析出；滤去杂质后倒入模具，自然冷却凝固成冻；切块装盘，蘸酱油、芥末、蒜蓉和香菜调的料汁。','闽南特色冷食，因原料形似笋而得名，其实是一种海虫。',1580,'思明区','flavornav/foods/2026/11/22ab8e5d1d3e462bb623de26cfada846.jpg',6,'老饕不挑食',1,143,'2026-11-10 20:14:42','2026-11-10 20:15:47','鲜、清爽','零食小食'),(96,'重庆小面','面条筋道，红油辣得直爽，花椒的麻在后半段才上来。榨菜和花生的脆、青菜的嫩，让一碗素面也层次丰富。','碱水面、辣椒油、花椒面、榨菜、花生、青菜','碗底放辣椒油、花椒面、酱油、蒜水和猪油；面条下锅煮至断生，连汤带面舀入碗中；铺上烫熟的青菜，撒榨菜末、花生碎和葱花，拌开吃。','重庆人的早饭，二两小面加一个煎蛋是标准配置。',312,'江北区','flavornav/foods/2026/11/5bbc0574eb2a4847897c55dd950bf38d.jpg',7,'一只咸鱼干',1,76,'2026-11-10 20:14:43','2026-11-10 20:15:47','辣、麻、香','主食'),(97,'驴打滚','糯米皮卷上红豆沙，再裹一层炒香的黄豆面切段。外层豆香干爽，内里软糯拉丝，豆沙的甜和黄豆的香混在一起，是孩子们最爱的老北京点心。','糯米粉、红豆沙、熟黄豆面','糯米粉加水和成软面团，上锅蒸熟后擀成薄片，抹一层红豆沙卷起；表面裹满炒香的黄豆面，切成小段装盘。做的时候豆面飞扬，像驴在地上打滚扬尘，名字就是这么来的。','因最后一道工序要在黄豆面里滚，形似驴打滚而得名，是北京传统小吃十三绝之一。',40,'房山区','flavornav/foods/2026/11/d0d3a6c8ed554cbc8b9808caa93548ff.jpg',8,'巷口那家店',1,214,'2026-11-10 20:14:43','2026-11-10 20:15:47','甜、香','甜品冻品'),(98,'龙抄手','皮薄得透光，包着紧实的肉馅，清汤版汤鲜味醇，红油版麻辣回甜。一口一个，皮滑馅嫩，汤也要喝干净，是成都人从小吃到大的味道。','面皮、猪后腿肉馅、鸡蛋、清汤或红油','猪后腿肉剁茸，加蛋清、姜水顺一个方向搅打上劲；面皮包入馅料，对折捏成元宝状；清汤版用鸡骨猪骨熬的高汤，红油版则浇红油、蒜泥和芝麻。煮抄手要水宽火旺，浮起即熟。','成都老字号，创于二十世纪四十年代，最初以抄手皮薄馅嫩闻名春熙路。',2409,'成华区','flavornav/foods/2026/11/b8812d44e6ff4b3c8da316a8d0606fca.jpg',9,'锅气爱好者',1,260,'2026-11-10 20:14:43','2026-11-10 20:15:47','鲜、香','主食'),(99,'符离集烧鸡','鸡皮金黄油亮，轻轻一撕就脱骨，肉里浸满香料的味道。冷吃最香，是宿州人走亲访友必带的特产。','土鸡、老汤、蜂蜜、香料','鸡宰杀造型后抹一层蜂蜜，下油锅炸至金黄；放入老汤，加八角、桂皮、白芷等香料，小火焖煮数小时至肉烂脱骨；捞出晾凉，表皮油亮、香味入骨。','安徽四大名鸡之一，与德州扒鸡、道口烧鸡齐名。',1540,'埇桥区','flavornav/foods/2026/11/7d02453f8a874bb1b930c6ce03ae8e3c.jpg',10,'碳水收割机',1,81,'2026-11-10 20:14:43','2026-11-10 20:15:47','香、咸','菜肴'),(100,'德州扒鸡','鸡皮金黄油亮，肉烂到骨头都能嚼，五香味渗进每一丝肉里。冷吃热吃都香，撕着吃最过瘾，是山东人走亲访友的伴手礼。','三黄鸡、老汤、八角、桂皮、丁香','鸡宰杀造型后抹蜂蜜，下油锅炸至金黄；放入老汤，加香料包，大火烧开转小火焖煮数小时，至骨肉分离、轻轻一抖就脱骨，捞出晾凉即可。','始于清代，有天下第一鸡之称，是火车时代最出名的山东特产。',1852,'德城区','flavornav/foods/2026/11/208035c653864059b1749f8726a7f5c4.jpg',11,'今天也要好好吃饭',1,162,'2026-11-10 20:14:43','2026-11-10 20:15:47','香、咸','菜肴');
